export function initChapterList(i,c,a={}){const s=document.getElementById(c);s&&(s.innerHTML="",i.forEach(t=>{const l=i.indexOf(t)+1,n=l.toString().padStart(2,"0");let e;if(a.type==="link")e=document.createElement("a"),e.href=t.url,e.className="chapter-card",e.innerHTML=`
                <div class="chap-badge">${n}</div>
                <div class="chap-info">
                    <div class="chap-title">${t.name}</div>
                    <div class="chap-meta">${a.metaText||'<i class="far fa-file-alt"></i> Practice Worksheets'}</div>
                </div>
                <div class="action-icon">
                    <i class="fas fa-chevron-right"></i>
                </div>
            `;else{e=document.createElement("div"),e.className="chapter-card";const d=a.getMeta?a.getMeta(t):"Resources",r=a.generateLinks?a.generateLinks(t,l):"";e.innerHTML=`
                <div class="card-header">
                    <div class="chap-badge">${n}</div>
                    <div class="chap-info">
                        <div class="chap-title">${t.name}</div>
                        <div class="chap-meta">${d}</div>
                    </div>
                    <div class="toggle-icon">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                </div>
                <div class="exercise-panel">
                    <div class="exercise-list">
                        ${r}
                    </div>
                </div>
            `,e.querySelector(".card-header").addEventListener("click",o=>{o.stopPropagation(),v(e)})}s.appendChild(e)}))}function v(i){const c=i.querySelector(".exercise-panel"),a=i.classList.contains("active");document.querySelectorAll(".chapter-card.active").forEach(s=>{s!==i&&(s.classList.remove("active"),s.querySelector(".exercise-panel").style.maxHeight=null)}),i.classList.toggle("active"),a?c.style.maxHeight=null:c.style.maxHeight=c.scrollHeight+"px"}
